package com.applypilot.cv;

import java.util.Optional;

/**
 * Where CV files are kept. The rest of the application only knows this interface, so the
 * local-disk implementation can be replaced by cloud storage (S3, R2, ...) without touching
 * the service or the controller.
 *
 * <p>Keys are generated by the application, never taken from user input.
 */
public interface CvStorage {

	void store(String key, byte[] content);

	/** Returns the file's bytes, or empty if nothing is stored under that key. */
	Optional<byte[]> load(String key);

	/** Deletes the file if it exists; deleting a missing key is not an error. */
	void delete(String key);

}
